public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                length += checkHorizontal(mat, i, j, length);
                length += checkVertical(mat, i, j, length);
                length += checkDiagonal(mat, i, j, length);
                length += checkAntiDiagonal(mat, i, j, length);
            }
        }
    }
    return maxLength;
}

private static int checkHorizontal(int[][] mat, int i, int j, int length) {
    int maxLength = length;
    while (j < mat[i].length - 1 && mat[i][j + 1] == 1) {
        j++;
        length++;
    }
    return maxLength;
}

private static int checkVertical(int[][] mat, int i, int j, int length) {
    int maxLength = length;
    while (i < mat.length - 1 && mat[i + 1][j] == 1) {
        i++;
        length++;
    }
    return maxLength;
}

private static int checkDiagonal(int[][] mat, int i, int j, int length) {
    int maxLength = length;
    int diagonal = 1;
    while (i < mat.length - 1 && j < mat[i].length - 1 && mat[i + 1][j + 1] == 1) {
        i++;
        j++;
        diagonal++;
    }
    return Math.max(maxLength, diagonal);
}

private static int checkAntiDiagonal(int[][] mat, int i, int j, int length) {
    int maxLength = length;
    int antiDiagonal = 1;
    while (i > 0 && j < mat[i].length - 1 && mat[i - 1][j + 1] == 1) {
        i--;
        j++;
        antiDiagonal++;
    }
    return Math.max(maxLength, antiDiagonal);
}
